import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
}

test('merges multiple branches recursively, retaining omitted keys and adding new ones', () => {
  const defaults = freeze({
    server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: { path: 'old.pem', mode: 420 } } },
    client: { retries: 3, headers: { accept: 'json', agent: 'default' } },
    untouched: 7
  });
  const overrides = freeze({
    server: { port: 9090, tls: { cert: { path: 'new.pem' }, timeout: 10 } },
    client: { headers: { agent: 'custom', extra: 'yes' } },
    added: { nested: { flag: true } }
  });
  const beforeDefaults = structuredClone(defaults);
  const beforeOverrides = structuredClone(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: 'new.pem', mode: 420 }, timeout: 10 } },
    client: { retries: 3, headers: { accept: 'json', agent: 'custom', extra: 'yes' } },
    untouched: 7, added: { nested: { flag: true } }
  });
  assert.deepEqual(defaults, beforeDefaults);
  assert.deepEqual(overrides, beforeOverrides);
});

test('empty plain overrides retain defaults at every depth', () => {
  assert.deepEqual(mergeConfig({ a: { b: { c: 1 }, d: 2 } }, { a: { b: {} } }), { a: { b: { c: 1 }, d: 2 } });
  assert.deepEqual(mergeConfig({ a: { b: 1 } }, { a: {} }), { a: { b: 1 } });
});

test('recursive merging is not limited to a fixed number of levels', () => {
  let defaults = { keep: 'leaf', change: 1 };
  let overrides = { change: 2, added: true };
  let expected = { keep: 'leaf', change: 2, added: true };
  for (let i = 0; i < 40; i++) {
    defaults = { keep: i, child: defaults };
    overrides = { child: overrides };
    expected = { keep: i, child: expected };
  }
  assert.deepEqual(mergeConfig(freeze(defaults), freeze(overrides)), expected);
});

test('non-object overrides replace nested defaults rather than being recursively combined', () => {
  for (const value of [null, undefined, false, 0, '', 'replacement', ['c']]) {
    const defaults = freeze({ outer: { sibling: 1, target: { old: true } } });
    const overrides = freeze({ outer: { target: value } });
    assert.deepEqual(mergeConfig(defaults, overrides), { outer: { sibling: 1, target: value } });
  }
  assert.deepEqual(mergeConfig({ outer: { sibling: 1, tags: ['a', 'b'] } }, { outer: { tags: ['c'] } }), { outer: { sibling: 1, tags: ['c'] } });
});

test('null-prototype dictionaries participate in recursive merging', () => {
  const defaults = { section: Object.assign(Object.create(null), { keep: 1, inner: { left: true, right: false } }) };
  const overrides = { section: Object.assign(Object.create(null), { inner: { right: true } }) };
  const result = mergeConfig(defaults, overrides);
  assert.equal(result.section.keep, 1);
  assert.deepEqual({ ...result.section.inner }, { left: true, right: true });
  assert.deepEqual(Object.keys(result.section).sort(), ['inner', 'keep']);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

test('flat keys retain existing spread semantics including explicit undefined', () => {
  const symbol = Symbol('key');
  const defaults = Object.freeze({ keep: true, level: 'info', remove: 1, [symbol]: 'old' });
  const overrides = Object.freeze({ level: 'debug', remove: undefined, added: 3, [symbol]: 'new' });
  assert.deepEqual(mergeConfig(defaults, overrides), { keep: true, level: 'debug', remove: undefined, added: 3, [symbol]: 'new' });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ x: 1 }, {}), { x: 1 });
  assert.deepEqual(mergeConfig({}, { x: 1 }), { x: 1 });
});

test('non-plain override values replace the entire default', () => {
  class Box { constructor() { this.value = 2; } }
  const values = [null, undefined, false, true, 0, 12, '', 'text', ['c'], new Date(0), new Box(), new Map([['x', 1]]), /x/];
  for (const value of values) {
    for (const original of [{ old: 1 }, ['a', 'b'], null, 'old', 5]) {
      const defaults = Object.freeze({ target: original, keep: 1 });
      const overrides = Object.freeze({ target: value });
      const result = mergeConfig(defaults, overrides);
      assert.deepEqual(result, { target: value, keep: 1 });
      assert.deepEqual(defaults, { target: original, keep: 1 });
      assert.deepEqual(overrides, { target: value });
    }
  }
});

test('plain objects can replace non-plain defaults', () => {
  for (const value of [null, undefined, false, 1, 'old', ['a', 'b']]) {
    assert.deepEqual(mergeConfig({ target: value }, { target: { fresh: true } }), { target: { fresh: true } });
  }
});

test('inherited and non-enumerable top-level keys are not copied', () => {
  const defaults = Object.assign(Object.create({ inherited: 1 }), { own: 2 });
  Object.defineProperty(defaults, 'hidden', { value: 3 });
  const overrides = Object.assign(Object.create({ ignored: 4 }), { added: 5 });
  assert.deepEqual(mergeConfig(defaults, overrides), { own: 2, added: 5 });
});
